from ortools.linear_solver import pywraplp
import math
import json

def main():
    N = 9
    customers = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I']

    coord = {
        'dispatch': (75, 98),
        'A': (62, 90),
        'B': (41, 77),
        'C': (36, 92),
        'D': (23, 65),
        'E': (24, 2),
        'F': (36, 10),
        'G': (73, 35),
        'H': (61, 24),
        'I': (30, 57)
    }

    all_locations = ['dispatch'] + customers

    dist = {}
    for i in all_locations:
        for j in all_locations:
            if i == j:
                dist[(i, j)] = 0
            else:
                x1, y1 = coord[i]
                x2, y2 = coord[j]
                dist[(i, j)] = math.sqrt((x1 - x2)**2 + (y1 - y2)**2)

    solver = pywraplp.Solver.CreateSolver('SCIP')
    if not solver:
        return

    x = {}
    for i in all_locations:
        for j in all_locations:
            x[(i, j)] = solver.BoolVar(f'x[{i},{j}]')

    u = {}
    for i in customers:
        u[i] = solver.IntVar(1, N, f'u[{i}]')

    solver.Add(sum(x[('dispatch', j)] for j in customers) == 1)

    solver.Add(sum(x[(i, 'dispatch')] for i in customers) == 1)

    for i in customers:
        solver.Add(sum(x[(i, j)] for j in all_locations if j != i) == 1)

    for i in customers:
        solver.Add(sum(x[(j, i)] for j in all_locations if j != i) == 1)

    for i in customers:
        for j in customers:
            if i != j:
                solver.Add(u[i] - u[j] + N * x[(i, j)] <= N - 1)

    for i in all_locations:
        solver.Add(x[(i, i)] == 0)

    objective = solver.Sum(dist[(i, j)] * x[(i, j)] for i in all_locations for j in all_locations)
    solver.Minimize(objective)

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL:
        tour = ['dispatch']
        current = 'dispatch'

        while True:
            for j in all_locations:
                if j != current and x[(current, j)].solution_value() > 0.5:
                    tour.append(j)
                    current = j
                    break

            if current == 'dispatch':
                break

        total_distance = 0
        for i in range(len(tour) - 1):
            from_loc = tour[i]
            to_loc = tour[i + 1]
            total_distance += dist[(from_loc, to_loc)]

        location_to_index = {'dispatch': 0}
        for idx, customer in enumerate(customers, start=1):
            location_to_index[customer] = idx

        tour_indices = [location_to_index[loc] for loc in tour]

        print(json.dumps({
            "tour": tour_indices,
            "total_distance": round(total_distance, 2)
        }))
    else:
        print(json.dumps({
            "tour": [],
            "total_distance": 0.0
        }))

if __name__ == '__main__':
    main()
